window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dea81d66ac553c33"]={"versions": [{"id": "FIG-dea81d66ac553c33", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Modelldefinition / Konzeptdiagramm zur Festlegung der Port-Richtungseigenschaft (<code>direction</code>) von Hardware-Ports im AUTOSAR-ECU-Ressourcen-Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Element</strong>: Repräsentiert eine Hardware-Entität (z. B. Controller, Sensor, Aktor oder Pin-Gruppe).\n</li><li><strong>Hardware-Ports</strong> (drei rechteckige Schnittstellenblöcke am rechten Rand):\n<ul class=\"fig-list\"><li>Oberer Port: Ausgangsrichtung, symbolisiert durch einen nach außen gerichteten Pfeil (<code>-&gt;</code>) mit Beschriftung <code>O</code> (Output).\n</li><li>Mittlerer Port: Eingangsrichtung, symbolisiert durch einen nach innen gerichteten Pfeil (<code>&lt;-</code>) mit Beschriftung <code>I</code> (Input).\n</li><li>Unterer Port: Bidirektionale Richtung, symbolisiert durch einen Doppelpfeil (<code>&lt;-&gt;</code>) mit Beschriftung <code>I</code> (bzw. In/Out / <code>IO</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeitsequenz. Es definiert die Flussrichtung von Signalen oder elektrischen Größen über HW-Ports (ausgehend, eingehend oder bidirektional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für die Modellierung von Hardware-Ressourcen: Ports von Hardware-Elementen müssen entsprechend ihrer physikalischen bzw. logischen Wirkrichtung als <code>Output</code>, <code>Input</code> oder bidirektional (<code>InOut</code>) deklariert werden.</p>"}, {"id": "FIG-6d0ecf2be8fa6154", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Modelldefinition / Konzeptdiagramm zur Festlegung der Port-Richtungseigenschaft (<code>direction</code>) von Hardware-Ports im AUTOSAR-ECU-Ressourcen-Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Element</strong> (linker Randbereich): Fragmentiert dargestellte übergeordnete Hardware-Entität ohne expliziten Textbezeichner.\n</li><li><strong>Hardware-Ports</strong> (drei rechteckige Schnittstellenblöcke am rechten Rand):\n<ul class=\"fig-list\"><li>Oberer Port: Ausgangsrichtung, symbolisiert durch einen nach außen gerichteten Pfeil (<code>-&gt;</code>) mit Beschriftung <code>O</code> (Output).\n</li><li>Mittlerer Port: Eingangsrichtung, symbolisiert durch einen nach innen gerichteten Pfeil (<code>&lt;-</code>) mit Beschriftung <code>I</code> (Input).\n</li><li>Unterer Port: Bidirektionale Richtung, symbolisiert durch einen Doppelpfeil (<code>&lt;-&gt;</code>) mit Beschriftung <code>I</code> (bzw. In/Out / <code>IO</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeitsequenz. Es definiert die Flussrichtung von Signalen oder elektrischen Größen über HW-Ports (ausgehend, eingehend oder bidirektional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für die Modellierung von Hardware-Ressourcen: Ports von Hardware-Elementen müssen entsprechend ihrer physikalischen bzw. logischen Wirkrichtung als <code>Output</code>, <code>Input</code> oder bidirektional (<code>InOut</code>) deklariert werden.</p>"}], "trans": [{"from": "FIG-dea81d66ac553c33", "to": "FIG-6d0ecf2be8fa6154", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Hardware-Element: Das übergeordnete Rechteck ist auf der linken Seite beschnitten; der Textinhalt „HW Element“ ist im Bildausschnitt nicht mehr sichtbar.\n</li></ul>"}]};
